import{_ as s,o as n,c as t,ag as r}from"./chunks/framework.C15dTZqp.js";const m=JSON.parse(`{"title":"Risques, gouvernance et coûts","description":"","frontmatter":{},"headers":[],"relativePath":"handout-05-risques-et-couts.md","filePath":"handout-05-risques-et-couts.md","handout":{"fichier":"handout-05-risques-et-couts.md","markdown":"# Handout — Risques, gouvernance et coûts\\n\\n**Speed training IA · Zenika · fiche module 5**\\n\\nCe qui peut mal tourner, les deux règles qui couvrent l'essentiel, et ce qui fait monter la facture.\\n\\n## 5 risques, 5 garde-fous\\n\\n| Risque               | En une phrase                                                 | Exemple                                                            | Garde-fou                                  |\\n| -------------------- | ------------------------------------------------------------- | ------------------------------------------------------------------ | ------------------------------------------ |\\n| **Hallucination**    | une réponse fausse mais convaincante                          | des avocats sanctionnés pour avoir cité une jurisprudence inventée | relecture, grounding (sources vérifiables) |\\n| **Prompt injection** | un contenu piégé (document, email, page web) détourne l'agent | des données exfiltrées via un document partagé                     | accès de l'agent limités                   |\\n| **Fuite de données** | des informations sensibles sortent de l'entreprise            | des secrets industriels collés dans un chatbot grand public        | versions entreprise des assistants         |\\n| **Biais**            | des stéréotypes reproduits, parfois amplifiés                 | des biais régionaux mesurés dans les réponses de LLM testés        | relire ce qui est sensible                 |\\n| **Coûts**            | une consommation qui s'emballe                                | des clés d'accès volées, des factures à 5 chiffres                 | plafonds de dépense, suivi                 |\\n\\n## 2 règles d'or\\n\\n**1. Données sensibles : uniquement dans les versions entreprise.** Rien de confidentiel dans un assistant grand public : clients, contrats, données personnelles, code. Les versions entreprise s'engagent par contrat à ne pas entraîner les modèles sur vos données. Les données personnelles restent soumises au RGPD : base légale, information des personnes, avis du DPO.\\n_Le test : l'enverriez-vous par email à un inconnu ?_\\n\\n**2. Un humain valide avant d'agir.** Obligatoire pour ce qui est irréversible, réglementé ou visible par un client. Cette validation est prévue dans le process, pas optionnelle, et faite par quelqu'un qui connaît le métier.\\n_Le test : qui signe si c'est faux ?_\\n\\nCes deux règles traitent la **fuite** d'un côté et l'**erreur** de l'autre. La seconde s'appelle le **human-in-the-loop**. Plus vous branchez de documents et de tools sur un assistant, plus elles comptent : un agent agit avec vos droits.\\n\\nCôté réglementation, l'AI Act européen impose depuis février 2025 que les personnes qui utilisent l'IA dans l'entreprise y soient formées (article 4), et le RGPD s'applique à toute donnée personnelle confiée à un assistant.\\n\\n## Coûts : le token se paie\\n\\n- Les modèles se paient au **token**, en entrée comme en sortie.\\n- L'historique est **renvoyé à chaque message** : une longue conversation coûte de plus en plus cher.\\n- En abonnement, la limite prend la forme de quotas ; à l'usage (API, agents), elle prend la forme d'une facture. Dans les deux cas, une consommation élevée traduit souvent un **usage non optimisé**.\\n\\n5 réflexes pour consommer moins :\\n\\n1. **1 tâche = 1 session** : moins d'historique renvoyé.\\n2. **Être précis** : une demande vague déclenche des recherches inutiles.\\n3. **Couper les connecteurs (MCP) inutiles** : chacun pèse dans le contexte.\\n4. **Garder le même modèle** pendant une session : sinon le **cache** (le début du contexte déjà traité) est perdu.\\n5. **Demander des réponses concises** : moins de tokens en sortie.\\n\\n## À retenir\\n\\n1. Rien de confidentiel hors des **versions entreprise**.\\n2. Un **humain qualifié valide** ce qui est irréversible, réglementé ou visible par un client.\\n3. Les sources se **vérifient** ; les accès des agents se **limitent**.\\n4. Sessions courtes et demandes précises : c'est meilleur pour la qualité **et** pour la facture.\\n\\n**Mots-clés** : hallucination, prompt injection, fuite de données, biais, grounding, human-in-the-loop, token, cache — voir le glossaire.\\n"}}`),o={name:"handout-05-risques-et-couts.md"};function i(a,e,l,u,d,c){return n(),t("div",null,[...e[0]||(e[0]=[r('<p class="zh-type">fiche module 5</p><h1 id="handout-risques-gouvernance-et-couts" tabindex="-1">Risques, gouvernance et coûts <a class="header-anchor" href="#handout-risques-gouvernance-et-couts" aria-label="Permalink to &quot;Handout — Risques, gouvernance et coûts&quot;">​</a></h1><p>Ce qui peut mal tourner, les deux règles qui couvrent l’essentiel, et ce qui fait monter la facture.</p><h2 id="5-risques-5-garde-fous" tabindex="-1">5 risques, 5 garde-fous <a class="header-anchor" href="#5-risques-5-garde-fous" aria-label="Permalink to &quot;5 risques, 5 garde-fous&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risque</th><th>En une phrase</th><th>Exemple</th><th>Garde-fou</th></tr></thead><tbody><tr><td><strong>Hallucination</strong></td><td>une réponse fausse mais convaincante</td><td>des avocats sanctionnés pour avoir cité une jurisprudence inventée</td><td>relecture, grounding (sources vérifiables)</td></tr><tr><td><strong>Prompt injection</strong></td><td>un contenu piégé (document, email, page web) détourne l’agent</td><td>des données exfiltrées via un document partagé</td><td>accès de l’agent limités</td></tr><tr><td><strong>Fuite de données</strong></td><td>des informations sensibles sortent de l’entreprise</td><td>des secrets industriels collés dans un chatbot grand public</td><td>versions entreprise des assistants</td></tr><tr><td><strong>Biais</strong></td><td>des stéréotypes reproduits, parfois amplifiés</td><td>des biais régionaux mesurés dans les réponses de LLM testés</td><td>relire ce qui est sensible</td></tr><tr><td><strong>Coûts</strong></td><td>une consommation qui s’emballe</td><td>des clés d’accès volées, des factures à 5 chiffres</td><td>plafonds de dépense, suivi</td></tr></tbody></table><h2 id="2-regles-d-or" tabindex="-1">2 règles d’or <a class="header-anchor" href="#2-regles-d-or" aria-label="Permalink to &quot;2 règles d&#39;or&quot;">​</a></h2><p><strong>1. Données sensibles : uniquement dans les versions entreprise.</strong> Rien de confidentiel dans un assistant grand public : clients, contrats, données personnelles, code. Les versions entreprise s’engagent par contrat à ne pas entraîner les modèles sur vos données. Les données personnelles restent soumises au RGPD : base légale, information des personnes, avis du DPO. <em>Le test : l’enverriez-vous par email à un inconnu ?</em></p><p><strong>2. Un humain valide avant d’agir.</strong> Obligatoire pour ce qui est irréversible, réglementé ou visible par un client. Cette validation est prévue dans le process, pas optionnelle, et faite par quelqu’un qui connaît le métier. <em>Le test : qui signe si c’est faux ?</em></p><p>Ces deux règles traitent la <strong>fuite</strong> d’un côté et l’<strong>erreur</strong> de l’autre. La seconde s’appelle le <strong>human-in-the-loop</strong>. Plus vous branchez de documents et de tools sur un assistant, plus elles comptent : un agent agit avec vos droits.</p><p>Côté réglementation, l’AI Act européen impose depuis février 2025 que les personnes qui utilisent l’IA dans l’entreprise y soient formées (article 4), et le RGPD s’applique à toute donnée personnelle confiée à un assistant.</p><h2 id="couts-le-token-se-paie" tabindex="-1">Coûts : le token se paie <a class="header-anchor" href="#couts-le-token-se-paie" aria-label="Permalink to &quot;Coûts : le token se paie&quot;">​</a></h2><ul><li>Les modèles se paient au <strong>token</strong>, en entrée comme en sortie.</li><li>L’historique est <strong>renvoyé à chaque message</strong> : une longue conversation coûte de plus en plus cher.</li><li>En abonnement, la limite prend la forme de quotas ; à l’usage (API, agents), elle prend la forme d’une facture. Dans les deux cas, une consommation élevée traduit souvent un <strong>usage non optimisé</strong>.</li></ul><p>5 réflexes pour consommer moins :</p><ol><li><strong>1 tâche = 1 session</strong> : moins d’historique renvoyé.</li><li><strong>Être précis</strong> : une demande vague déclenche des recherches inutiles.</li><li><strong>Couper les connecteurs (MCP) inutiles</strong> : chacun pèse dans le contexte.</li><li><strong>Garder le même modèle</strong> pendant une session : sinon le <strong>cache</strong> (le début du contexte déjà traité) est perdu.</li><li><strong>Demander des réponses concises</strong> : moins de tokens en sortie.</li></ol><h2 id="a-retenir" tabindex="-1">À retenir <a class="header-anchor" href="#a-retenir" aria-label="Permalink to &quot;À retenir&quot;">​</a></h2><ol><li>Rien de confidentiel hors des <strong>versions entreprise</strong>.</li><li>Un <strong>humain qualifié valide</strong> ce qui est irréversible, réglementé ou visible par un client.</li><li>Les sources se <strong>vérifient</strong> ; les accès des agents se <strong>limitent</strong>.</li><li>Sessions courtes et demandes précises : c’est meilleur pour la qualité <strong>et</strong> pour la facture.</li></ol><p><strong>Mots-clés</strong> : hallucination, prompt injection, fuite de données, biais, grounding, human-in-the-loop, token, cache — voir le glossaire.</p>',17)])])}const g=s(o,[["render",i]]);export{m as __pageData,g as default};
